<?php
declare(strict_types=1);
require_once __DIR__.'/includes/session_org.php';
require_once __DIR__.'/includes/org_context.php';
require_once __DIR__.'/includes/org_manager_guard.php';
require_once __DIR__.'/../public_user/includes/org_shop.php';
require_once __DIR__.'/includes/org_ecommerce.php';
org_require_manager(); org_require_commerce_seller(); org_shop_ensure_schema($dbh);
if(!function_exists('h')){function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}}
$orgId=(int)orgActiveOrgId(); $money=static fn(int $v):string=>org_sales_money($v);
$orders=[]; try{$st=$dbh->prepare("SELECT id,buyer_email,product_title,quantity,total_cents,created_at FROM org_orders WHERE org_id=:org ORDER BY created_at DESC");$st->execute([':org'=>$orgId]);$orders=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){}
$now=time();$start=$now-6*86400;$prevStart=$start-7*86400;$sales=0;$prevSales=0;$orderCount=0;$prevOrders=0;$customers=[];$prevCustomers=[];$days=array_fill(0,7,0);$products=[];
foreach($orders as $o){$ts=strtotime((string)$o['created_at'])?:0;$amount=(int)$o['total_cents'];$email=strtolower(trim((string)($o['buyer_email']??'')));if($ts>=$start){$sales+=$amount;$orderCount++;if($email!=='')$customers[$email]=1;$idx=max(0,min(6,(int)floor(($ts-$start)/86400)));$days[$idx]+=$amount;$p=trim((string)($o['product_title']??''))?:'Product';if(!isset($products[$p]))$products[$p]=['orders'=>0,'sales'=>0];$products[$p]['orders']+=(int)max(1,(int)($o['quantity']??1));$products[$p]['sales']+=$amount;}elseif($ts>=$prevStart){$prevSales+=$amount;$prevOrders++;if($email!=='')$prevCustomers[$email]=1;}}
uasort($products,static fn(array $a,array $b)=>(int)$b['sales']<=>(int)$a['sales']);$products=array_slice($products,0,5,true);$avg=$orderCount?(int)round($sales/$orderCount):0;$customerCount=count($customers);$conversion=$customerCount?min(99.9,round($orderCount/max(1,$customerCount*16)*100,2)):0;
$change=static fn(int $a,int $b):string=>$b===0?($a>0?'100.0':'0.0'):number_format((($a-$b)/$b)*100,1);
$maxDay=max(1,max($days));$points=[];foreach($days as $i=>$v){$points[]=(30+$i*88).','.round(150-($v/$maxDay)*105);}$pointsText=implode(' ',$points);$analyticsEmbedded=!empty($analyticsEmbedded);
if(!$analyticsEmbedded){$pageTitle='Analytics';require_once __DIR__.'/includes/org_page_shell.php';org_page_shell_open($pageTitle,'<link rel="stylesheet" href="css/commerce-hub.css?v=17">');org_page_body_open('commerce-page');}
?>
