<section class="an-kpis"><?php foreach([["fa-dollar",'','Total Sales',$money($sales),$change($sales,$prevSales).'%' ],['fa-shopping-bag','green','Total Orders',(string)$orderCount,$change($orderCount,$prevOrders).'%'],['fa-shopping-cart','orange','Avg. Order Value',$money($avg),'Current period'],['fa-user-o','purple','Total Customers',(string)$customerCount,'Active buyers'],['fa-line-chart','cyan','Conversion Rate',number_format($conversion,2).'%','Store visits estimate']] as $k):?><div class="an-kpi"><i class="fa <?=$k[0]?> an-icon <?=$k[1]?>"></i><div><small><?=$k[2]?></small><strong><?=h($k[3])?></strong><span>↑ <?=h($k[4])?></span></div></div><?php endforeach;?></section>
<div class="an-grid"><section class="an-card an-sales"><h2>Sales Overview</h2><svg class="an-chart" viewBox="0 0 590 180" preserveAspectRatio="none"><?php for($y=25;$y<=150;$y+=31):?><line x1="30" y1="<?=$y?>" x2="570" y2="<?=$y?>"/><?php endfor;?><polyline points="<?=h($pointsText)?>"/><?php foreach($days as $i=>$v):?><text x="<?=25+$i*88?>" y="173"><?=h(date('M j',$start+$i*86400))?></text><?php endforeach;?></svg><div class="an-stats"><div class="an-stat"><span>Total Sales</span><strong><?=h($money($sales))?></strong></div><div class="an-stat"><span>Total Orders</span><strong><?=$orderCount?></strong></div><div class="an-stat"><span>Avg. Order Value</span><strong><?=h($money($avg))?></strong></div><div class="an-stat"><span>Customers</span><strong><?=$customerCount?></strong></div></div></section><section class="an-card an-channel"><h2>Sales by Channel</h2><div class="an-donut-wrap"><div class="an-donut"></div><div class="an-legend"><div><i style="background:#155eef"></i>Online Store 57%</div><div><i style="background:#21bf73"></i>Mobile App 24%</div><div><i style="background:#ff9c17"></i>Marketplaces 13%</div><div><i style="background:#8d71ef"></i>Other 6%</div></div></div></section></div>
<div class="an-bottom"><section class="an-card an-products"><h2>Top Selling Products</h2><table class="an-table"><tr><th>Product</th><th>Orders</th><th>Sales</th></tr><?php if(!$products):?><tr><td colspan="3">No sales in this period.</td></tr><?php endif;?><?php foreach($products as $name=>$p):?><tr><td><?=h($name)?></td><td><?=(int)$p['orders']?></td><td><?=h($money((int)$p['sales']))?></td></tr><?php endforeach;?></table></section><section class="an-card an-orders"><h2>Orders Overview</h2><div class="an-bars"><?php foreach($days as $v):?><div class="an-bar" style="height:<?=max(3,round($v/$maxDay*100))?>%"></div><?php endforeach;?></div><div class="an-stats" style="grid-template-columns:1fr 1fr"><div class="an-stat"><span>Total Orders</span><strong><?=$orderCount?></strong></div><div class="an-stat"><span>Avg. Orders / Day</span><strong><?=number_format($orderCount/7,1)?></strong></div></div></section><section class="an-card an-insights"><h2>Customer Insights</h2><div class="an-insight"><span>New Customers</span><b><?=$customerCount?></b><b>↑</b></div><div class="an-insight"><span>Returning Customers</span><b><?=count(array_intersect_key($customers,$prevCustomers))?></b><b>↑</b></div><div class="an-insight"><span>Customer Lifetime Value</span><b><?=h($money($avg))?></b><b>↑</b></div><div class="an-insight"><span>Repeat Purchase Rate</span><b><?=$customerCount?number_format(count(array_intersect_key($customers,$prevCustomers))/$customerCount*100,1):'0.0'?>%</b><b>↑</b></div></section></div></main>
